BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE owner uuid:=gen_random_uuid();user_id uuid:=gen_random_uuid();viewer_id uuid:=gen_random_uuid();member uuid;viewer uuid;key uuid;link uuid;hidden uuid;folder uuid;profile jsonb;reserved jsonb;second jsonb;asset uuid;claim jsonb;version uuid;
BEGIN
 INSERT INTO auth.users(id) VALUES(owner),(user_id),(viewer_id);INSERT INTO public.user_roles VALUES(owner,'admin');
 INSERT INTO public.redirect_workspace_members(user_id,kind,label) VALUES(user_id,'user','Branding editor') RETURNING id INTO member;
 INSERT INTO public.redirect_workspace_members(user_id,kind,label,role) VALUES(viewer_id,'user','Branding viewer','viewer') RETURNING id INTO viewer;
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','password-branded','https://example.org/private') RETURNING id INTO link;
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','password-brand-hidden','https://example.org/private') RETURNING id INTO hidden;
 INSERT INTO public.redirect_link_folders(name,default_permission) VALUES('Branding private','none') RETURNING id INTO folder;
 INSERT INTO public.redirect_link_metadata(redirect_key,folder_id) VALUES('redirects:'||hidden,folder);
 INSERT INTO public.redirect_api_tokens(name,token_hash,prefix,scopes,redirect_ids,created_by,expires_at) VALUES('Branding key',repeat('b',64),'fixture',ARRAY['links:read','links:write'],ARRAY[link],owner,now()+interval '1 day') RETURNING id INTO key;
 profile:=public.redirect_password_branding_resource('get',owner,NULL,link);
 IF profile->>'version' IS NOT NULL OR profile->>'logoAsset' IS NOT NULL OR NOT(profile->>'canEdit')::boolean THEN RAISE EXCEPTION 'Invalid initial branding';END IF;
 profile:=public.redirect_password_branding_resource('patch',owner,NULL,link,'{"version":null,"brandName":"Studio & <community>"}');version:=(profile->>'version')::uuid;
 BEGIN PERFORM public.redirect_password_branding_resource('patch',owner,NULL,link,'{"version":null,"brandName":"Stale"}');RAISE EXCEPTION 'Stale branding accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 BEGIN PERFORM public.redirect_password_branding_resource('get',NULL,key,hidden);RAISE EXCEPTION 'Hidden link branding leaked';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.redirect_password_branding_resource('get',owner,member,link);RAISE EXCEPTION 'Member impersonation accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF(public.redirect_password_branding_resource('get',viewer_id,viewer,link)->>'canEdit')::boolean THEN RAISE EXCEPTION 'Viewer can edit branding';END IF;
 BEGIN PERFORM public.redirect_password_branding_resource('patch',viewer_id,viewer,link,jsonb_build_object('version',version,'clearLogo',true));RAISE EXCEPTION 'Viewer edit accepted';EXCEPTION WHEN insufficient_privilege OR no_data_found THEN NULL;END;
 reserved:=public.reserve_redirect_password_logo(NULL,key,link,version,'image/png',100,64,64,repeat('a',64));asset:=(reserved->>'id')::uuid;
 BEGIN PERFORM public.finish_redirect_password_logo(owner,NULL,link,asset);RAISE EXCEPTION 'Different principal attached reservation';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 profile:=public.finish_redirect_password_logo(NULL,key,link,asset);
 IF profile->'logoAsset'->>'id'<>asset::text OR profile->>'brandName'<>'Studio & <community>' THEN RAISE EXCEPTION 'Logo attach lost branding';END IF;
 IF public.redirect_password_branding_public(link)?'version' OR public.redirect_password_branding_public(link)::text LIKE '%principalKey%' THEN RAISE EXCEPTION 'Public branding leaked private fields';END IF;
 UPDATE public.redirect_qr_assets SET next_cleanup_at=clock_timestamp()-interval '1 second' WHERE id=asset;
 claim:=public.claim_redirect_qr_asset_cleanup(5);IF EXISTS(SELECT FROM jsonb_array_elements(claim) e WHERE e->>'id'=asset::text) THEN RAISE EXCEPTION 'Attached password logo claimed for cleanup';END IF;
 version:=(profile->>'version')::uuid;
 reserved:=public.reserve_redirect_password_logo(user_id,member,link,version,'image/png',100,64,64,repeat('c',64));
 profile:=public.redirect_password_branding_resource('patch',owner,NULL,link,jsonb_build_object('version',version,'brandName','Concurrent owner edit'));
 BEGIN PERFORM public.finish_redirect_password_logo(user_id,member,link,(reserved->>'id')::uuid);RAISE EXCEPTION 'Late version overwrite accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 second:=public.reserve_redirect_password_logo(NULL,key,link,(profile->>'version')::uuid,'image/png',100,64,64,repeat('d',64));
 UPDATE public.redirect_api_tokens SET revoked_at=clock_timestamp() WHERE id=key;
 BEGIN PERFORM public.finish_redirect_password_logo(NULL,key,link,(second->>'id')::uuid);RAISE EXCEPTION 'Revoked key attached upload';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 profile:=public.redirect_password_branding_resource('patch',owner,NULL,link,jsonb_build_object('version',profile->>'version','clearLogo',true));
 IF profile->>'logoAsset' IS NOT NULL THEN RAISE EXCEPTION 'Clear did not remove logo';END IF;
 UPDATE public.redirect_qr_assets SET next_cleanup_at=clock_timestamp()-interval '1 second' WHERE id=asset;
 claim:=public.claim_redirect_qr_asset_cleanup(5);IF NOT EXISTS(SELECT FROM jsonb_array_elements(claim) e WHERE e->>'id'=asset::text) THEN RAISE EXCEPTION 'Released logo never claimed';END IF;
 reserved:=public.reserve_redirect_password_logo(owner,NULL,hidden,NULL,'image/jpeg',100,64,64,repeat('e',64));profile:=public.finish_redirect_password_logo(owner,NULL,hidden,(reserved->>'id')::uuid);
 DELETE FROM public.redirects WHERE id=hidden;
 IF EXISTS(SELECT FROM public.redirect_password_branding WHERE link_id=hidden) OR EXISTS(SELECT FROM public.redirect_qr_assets WHERE id=(reserved->>'id')::uuid AND password_link_id IS NOT NULL) THEN RAISE EXCEPTION 'Link deletion retained branding reference';END IF;
 reserved:=public.reserve_redirect_password_logo(owner,NULL,link,(SELECT b.version FROM public.redirect_password_branding b WHERE b.link_id=link),'image/png',100,64,64,repeat('f',64));
 DELETE FROM public.user_roles ur WHERE ur.user_id=owner;
 BEGIN PERFORM public.finish_redirect_password_logo(owner,NULL,link,(reserved->>'id')::uuid);RAISE EXCEPTION 'Former owner attached logo';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF has_table_privilege('authenticated','public.redirect_password_branding','SELECT') OR has_function_privilege('anon','public.redirect_password_branding_public(uuid)','EXECUTE') THEN RAISE EXCEPTION 'Private branding grants leaked';END IF;
END $$;
ROLLBACK;
